using System.Diagnostics;
using System.Globalization;
using System.Text.Json;
namespace CMCutLab;
internal record Cut(double Start,double End,string Reason){public bool Selected{get;set;} public double Length=>End-Start;}
internal record Media(double Duration,double Fps,int Channels,int Width,int Height){internal double DisplayAspect{get;init;}};
internal static class Engine
{
 internal static readonly string Home=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"infernoStudio");
 internal static string N(double n)=>n.ToString("0.######",CultureInfo.InvariantCulture);
 internal static string Time(double n)=>TimeSpan.FromSeconds(Math.Max(0,n)).ToString(@"hh\:mm\:ss\.fff");
 internal static string Tool(string name){var own=Path.Combine(AppContext.BaseDirectory,"MediaTools",name+".exe");if(File.Exists(own))return own;var pointer=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"ZooMediaTools","active.txt");if(File.Exists(pointer)){var file=Path.Combine(File.ReadAllText(pointer).Trim(),name+".exe");if(File.Exists(file))return file;}throw new FileNotFoundException("動画部品が見つかりません。Studioで導入済みの動画部品を参照します。");}
 internal static string DefaultFolder(){var own=Path.Combine(Home,"folder.txt");var legacy=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"CMCutLab","folder.txt");if(!File.Exists(own)&&File.Exists(legacy)){Directory.CreateDirectory(Home);File.Copy(legacy,own,false);}if(File.Exists(own)&&Directory.Exists(File.ReadAllText(own).Trim()))return File.ReadAllText(own).Trim();var studio=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"ZOOstudioPre","recording-folder.txt");return File.Exists(studio)&&Directory.Exists(File.ReadAllText(studio).Trim())?File.ReadAllText(studio).Trim():Environment.GetFolderPath(Environment.SpecialFolder.MyVideos);}
 internal static ProcessStartInfo Info(string tool,IEnumerable<string> args){var si=new ProcessStartInfo(Tool(tool)){UseShellExecute=false,CreateNoWindow=true,RedirectStandardError=true,RedirectStandardOutput=true};foreach(var arg in args)si.ArgumentList.Add(arg);return si;}
 internal static async Task<string> Run(string tool,IEnumerable<string> args,CancellationToken ct,Action<string>? error=null,Action<string>? progress=null){using var p=new Process{StartInfo=Info(tool,args)};p.Start();using var cancel=ct.Register(()=>{try{if(!p.HasExited)p.Kill(true);}catch(InvalidOperationException){}});var tail=new Queue<string>();async Task ReadError(){while(await p.StandardError.ReadLineAsync() is string line){if(tail.Count==20)tail.Dequeue();tail.Enqueue(line);error?.Invoke(line);}}async Task<string> ReadOut(){if(progress==null)return await p.StandardOutput.ReadToEndAsync();while(await p.StandardOutput.ReadLineAsync() is string line)progress(line);return "";}var errors=ReadError();string result=await ReadOut();await p.WaitForExitAsync(CancellationToken.None);await errors;ct.ThrowIfCancellationRequested();if(p.ExitCode!=0)throw new IOException(string.Join('\n',tail));return result;}
 internal static async Task<Media> Probe(string file,CancellationToken ct){string json=await Run("ffprobe",["-v","error","-show_entries","format=duration:stream=codec_type,width,height,avg_frame_rate,channels,duration,sample_aspect_ratio,display_aspect_ratio","-of","json",file],ct);using var d=JsonDocument.Parse(json);var streams=d.RootElement.GetProperty("streams").EnumerateArray().ToArray();var video=streams.First(s=>s.GetProperty("codec_type").GetString()=="video");string rate=video.GetProperty("avg_frame_rate").GetString()??"0/1";var parts=rate.Split('/');double fps=double.Parse(parts[0],CultureInfo.InvariantCulture)/Math.Max(1,double.Parse(parts.ElementAtOrDefault(1)??"1",CultureInfo.InvariantCulture));double duration=0;if(d.RootElement.TryGetProperty("format",out var f)&&f.TryGetProperty("duration",out var dur))double.TryParse(dur.GetString(),CultureInfo.InvariantCulture,out duration);if(duration<=0&&video.TryGetProperty("duration",out dur))double.TryParse(dur.GetString(),CultureInfo.InvariantCulture,out duration);if(duration<=0||!double.IsFinite(duration))throw new IOException("動画の長さを読み取れません。");var a=streams.FirstOrDefault(s=>s.GetProperty("codec_type").GetString()=="audio");int channels=a.ValueKind!=JsonValueKind.Undefined&&a.TryGetProperty("channels",out var ch)?ch.GetInt32():0;int width=video.GetProperty("width").GetInt32(),height=video.GetProperty("height").GetInt32();double aspect=(double)width/Math.Max(1,height);if(video.TryGetProperty("sample_aspect_ratio",out var sar)){var ratio=(sar.GetString()??"").Split(':');if(ratio.Length==2&&double.TryParse(ratio[0],CultureInfo.InvariantCulture,out var num)&&double.TryParse(ratio[1],CultureInfo.InvariantCulture,out var den)&&num>0&&den>0)aspect*=num/den;}return new(duration,fps>0?fps:29.97,channels,width,height){DisplayAspect=aspect};}
 internal static List<(double Start,double End)> Keep(IEnumerable<Cut> cuts,double duration){var selected=cuts.Where(c=>c.Selected).OrderBy(c=>c.Start).ToArray();double last=0;var result=new List<(double,double)>();foreach(var c in selected){if(!double.IsFinite(c.Start)||!double.IsFinite(c.End)||c.Start<0||c.End>duration+0.001||c.End<=c.Start)throw new InvalidDataException("カット範囲が動画の長さに収まりません。");if(c.Start>last)result.Add((last,c.Start));last=Math.Max(last,c.End);}if(last<duration)result.Add((last,duration));if(result.Count==0)throw new InvalidDataException("すべての映像を削除する指定です。");return result;}
 internal static string Filter(List<(double Start,double End)> keep,bool audio){var lines=new List<string>();for(int i=0;i<keep.Count;i++){var s=keep[i];lines.Add($"[0:v:0]trim=start={N(s.Start)}:end={N(s.End)},setpts=PTS-STARTPTS[v{i}]");if(audio)lines.Add($"[0:a:0]atrim=start={N(s.Start)}:end={N(s.End)},asetpts=PTS-STARTPTS[a{i}]");}lines.Add(string.Concat(Enumerable.Range(0,keep.Count).Select(i=>audio?$"[v{i}][a{i}]":$"[v{i}]"))+$"concat=n={keep.Count}:v=1:a={(audio?1:0)}[v]"+(audio?"[a]":""));return string.Join(';',lines);}
 internal static async Task Export(string file,string output,Media media,List<(double Start,double End)> keep,string codec,int bitrate,CancellationToken ct,Action<double> progress,RenderJob? job=null){string temp=Path.Combine(Path.GetDirectoryName(output)!,".cmcut-"+Guid.NewGuid().ToString("N")+".mp4");try{ct.ThrowIfCancellationRequested();using var lease=new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.Read);if(Path.GetFullPath(file).Equals(Path.GetFullPath(output),StringComparison.OrdinalIgnoreCase))throw new IOException("元ファイルには書き込めません。");if(File.Exists(output))throw new IOException("同名ファイルが存在します。");var args=new List<string>{"-hide_banner","-nostdin","-n","-threads","2","-filter_complex_threads","1","-i",file,"-filter_complex",Filter(keep,media.Channels>0),"-map","[v]"};if(media.Channels>0)args.AddRange(["-map","[a]","-c:a","aac","-b:a","192k"]);args.AddRange(["-c:v",codec,"-b:v",bitrate+"M"]);if(codec=="libsvtav1")args.AddRange(["-preset","12","-svtav1-params","lp=2"]);args.AddRange(["-pix_fmt","yuv420p","-movflags","+faststart","-progress","pipe:1","-nostats",temp]);double total=keep.Sum(s=>s.End-s.Start);await Run("ffmpeg",args,ct,line=>job?.Log(line),line=>{job?.Feed(line);if(line.StartsWith("out_time_us=")&&double.TryParse(line[12..],CultureInfo.InvariantCulture,out var us))progress(Math.Clamp(us/1e6/total,0,1));});ct.ThrowIfCancellationRequested();File.Move(temp,output,false);job?.Finish("完了");}catch(OperationCanceledException){job?.Finish("キャンセル済み");throw;}catch(Exception e){job?.Finish("失敗",e.Message);throw;}finally{if(File.Exists(temp))File.Delete(temp);}}
 internal static async Task<Bitmap> Frame(string file,double time,CancellationToken ct){string temp=Path.Combine(Home,"frame-"+Guid.NewGuid().ToString("N")+".png");Directory.CreateDirectory(Home);try{await Run("ffmpeg",["-v","error","-nostdin","-threads","2","-ss",N(Math.Max(0,time)),"-i",file,"-frames:v","1","-vf","scale=640:360:force_original_aspect_ratio=decrease,scale=trunc(iw*sar/2)*2:ih,setsar=1","-y",temp],ct);using var image=Image.FromFile(temp);return new Bitmap(image);}finally{if(File.Exists(temp))File.Delete(temp);}}
}
